    assert f('racecar') == 'racecar'

def test_none():
    assert f('abc') == 'a'

items.old_code:
def longest_palindromic_substring(s):
    if not s:
        return ''
    best = s[0]
    for center in range(len(s)):
        for lo, hi in ((center, center), (center, center + 1)):
            l, r = lo, hi
            while l >= 0 and r < len(s) and s[l] == s[r]:
                if r - l + 1 > len(best):
                    best = s[l:r + 1]
                l -= 1
                r += 1
    return best

