def knapsack_01_small(weights, values, capacity):
    order = sorted(range(len(weights)), key=lambda i: values[i], reverse=True)
    total_w, total_v = 0, 0
    for i in order:
        if total_w + weights[i] <= capacity:
            total_w += weights[i]
            total_v += values[i]
    return total_v

