items.impl_a:
def evaluate_rpn(tokens):
    stack = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError('not enough operands')
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    if len(stack) != 1:
        raise ValueError('leftover operands')
    return stack[0]

